<?php require 'config.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){$pid=(int)$_POST['product_id'];$s=$pdo->prepare('SELECT id FROM wishlist WHERE user_id=? AND product_id=?');$s->execute([user()['id'],$pid]);if($s->fetch())$pdo->prepare('DELETE FROM wishlist WHERE user_id=? AND product_id=?')->execute([user()['id'],$pid]);else $pdo->prepare('INSERT IGNORE INTO wishlist(user_id,product_id) VALUES(?,?)')->execute([user()['id'],$pid]);header('Location: wishlist.php');exit;}require 'header.php';$s=$pdo->prepare('SELECT p.* FROM wishlist w JOIN products p ON p.id=w.product_id WHERE w.user_id=?');$s->execute([user()['id']]);$items=$s->fetchAll();?>
<div class="container"><h1>รายการโปรด</h1><div class="grid"><?php foreach($items as $p):?><article class="product"><a href="product.php?id=<?=$p['id']?>"><?php if($p['image']):?><img src="<?=h($p['image'])?>"><?php else:?><div class="placeholder">🖥</div><?php endif;?></a><div class="product-body"><h3><?=h($p['name'])?></h3><div class="price">฿<?=money($p['price'])?></div><form method="post"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="btn secondary">เอาออกจากรายการ</button></form></div></article><?php endforeach;?></div><?php if(!$items):?><div class="empty">ยังไม่มีรายการโปรด</div><?php endif;?></div><?php require 'footer.php';?>
